mapper.select:
SELECT t.* FROM task_info t
                    JOIN carriage_info c ON t.source_carriage = c.id
WHERE c.train_id = #{trainId}

SELECT t.* FROM task_info t


        t.state = #{state}


        AND t.task_name LIKE CONCAT('%', #{taskName}, '%')


        AND t.source_device = #{deviceId}


ORDER BY t.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM task_info t


        t.state = #{state}


        AND t.task_name LIKE CONCAT('%', #{taskName}, '%')


        AND t.source_device = #{deviceId}
